{
        // Replace some key-names by single characters, so they can be pronounced in different languages
        static MNEM_TAB keynames[] = {
                { "space ",        0xe020 },
                { "tab ",          0xe009 },
                { "underscore ",   0xe05f },
                { "double-quote ", '"' },
